import java.util.Map;
public class PVCheck {
  static Map<String,String> CITY = Map.of("Sydney","NSW","Melbourne","VIC","Brisbane","QLD");
  static Map<String,int[]> R = Map.of("NSW",new int[]{2000,2099},"VIC",new int[]{3000,3099},"QLD",new int[]{4000,4099});
  static boolean valid(String city,String pc){
    if(pc==null||!pc.matches("[0-9]{4}")) return true;
    int[] r=R.get(CITY.getOrDefault(city,"UNKNOWN"));
    if(r==null) return true;
    int v=Integer.parseInt(pc); return v>=r[0]&&v<=r[1];
  }
  public static void main(String[] a){
    System.out.println("Sydney/2000 (expect true): "+valid("Sydney","2000"));
    System.out.println("Sydney/2100 (expect false): "+valid("Sydney","2100"));
    System.out.println("Melbourne/2000 (expect false): "+valid("Melbourne","2000"));
    System.out.println("Melbourne/3050 (expect true): "+valid("Melbourne","3050"));
    System.out.println("Brisbane/4099 (expect true): "+valid("Brisbane","4099"));
    System.out.println("TownX/2000 unknown region (expect true): "+valid("TownX","2000"));
    System.out.println("Sydney/null (expect true): "+valid("Sydney",null));
  }
}
EOF
